CREATE DATABASE IF NOT EXISTS school_canteen CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE school_canteen;
CREATE TABLE suppliers (id INT AUTO_INCREMENT PRIMARY KEY, supplier_name VARCHAR(150) NOT NULL, contact_person VARCHAR(120), contact_number VARCHAR(50), address TEXT, products_supplied TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, product_name VARCHAR(150) NOT NULL UNIQUE, default_unit VARCHAR(30) NOT NULL DEFAULT 'pcs', supplier_id INT NULL, FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY, supplier_id INT NOT NULL, reference_number VARCHAR(80) NULL, order_date DATE NOT NULL, expected_delivery_date DATE NOT NULL, notes TEXT, status ENUM('Pending','Scheduled','Delivered','Incomplete','Cancelled') NOT NULL DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE order_items (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL, product_id INT NULL, product_name VARCHAR(150) NOT NULL, quantity DECIMAL(10,2) NOT NULL, unit VARCHAR(30) NOT NULL, unit_price DECIMAL(10,2) NOT NULL DEFAULT 0, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE deliveries (id INT AUTO_INCREMENT PRIMARY KEY, order_id INT NOT NULL UNIQUE, reference_number VARCHAR(80) NULL, actual_delivery_date DATE NOT NULL, notes TEXT, status ENUM('Delivered','Incomplete') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE delivery_items (id INT AUTO_INCREMENT PRIMARY KEY, delivery_id INT NOT NULL, order_item_id INT NOT NULL, delivered_quantity DECIMAL(10,2) NOT NULL DEFAULT 0, FOREIGN KEY(delivery_id) REFERENCES deliveries(id) ON DELETE CASCADE, FOREIGN KEY(order_item_id) REFERENCES order_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE inventory (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NULL UNIQUE, product_name VARCHAR(150) NOT NULL UNIQUE, quantity DECIMAL(10,2) NOT NULL DEFAULT 0, unit VARCHAR(30) NOT NULL, low_stock_threshold DECIMAL(10,2) NOT NULL DEFAULT 10, supplier_id INT NULL, last_received DATE NULL, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL, FOREIGN KEY(supplier_id) REFERENCES suppliers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE stock_adjustments (id INT AUTO_INCREMENT PRIMARY KEY, inventory_id INT NOT NULL, previous_quantity DECIMAL(10,2) NOT NULL, new_quantity DECIMAL(10,2) NOT NULL, adjustment_reason VARCHAR(255) NOT NULL, adjusted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(inventory_id) REFERENCES inventory(id) ON DELETE CASCADE) ENGINE=InnoDB;
